import sys, os, json, optax
import numpy as np
import jax
import jax.numpy as jnp
from typing import Dict, Any
import flax.linen as nn

# Import network and system loaders
sys.path.append('storage/noema/submissions')
from dual_path_hybrid_motif_heads_regcal import build_network as build_hdp_regcal

sys.path.append('storage/system')
import train_single as ts  # provides load_dataset()

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'hidden_dim': 256,
        'd_model': 256,
        'kernel_size': 7,
        'dropout_rate': 0.10,
        'aggregator': 'mean_max',
        'motif_kernel_size': 5,
        'regcal_l2': True,
        'head_dropout': 0.05,
        'learning_rate': 0.001,
        'grad_clip': 1.0
    }

def create_network(hparams):
    return build_hdp_regcal(hparams.get('d_output', 1), hparams.get('task_type', 'regression'), hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=0.01))

# ------ Analysis helpers ------

def _task_spec(dataset: str):
    if dataset in ("APA", "CRI-Off", "CRI-On", "MRL"):
        return "regression", 1
    if dataset == "PRS":
        return "multilabel_regression", 3
    if dataset == "Modif":
        return "multilabel_classification", 12
    if dataset == "ncRNA":
        return "multiclass_classification", 13
    raise ValueError(f"Unknown dataset: {dataset}")

def _summarize(arr):
    arr = np.asarray(arr).reshape(-1)
    qs = np.quantile(arr, [0.05, 0.25, 0.50, 0.75, 0.95])
    return dict(mean=float(arr.mean()), std=float(arr.std()),
                q05=float(qs[0]), q25=float(qs[1]), q50=float(qs[2]),
                q75=float(qs[3]), q95=float(qs[4]), n=int(arr.size))

def _collect_z_pre_norms(params, dataset_name: str, hparams: Dict[str, Any]):
    task_type, d_out = _task_spec(dataset_name)
    # Rebuild an analysis module with regcal_l2=False, so head Dropout output equals fused z_pre
    hp = dict(hparams)
    hp.update({'task_type': task_type, 'd_output': d_out, 'regcal_l2': False})
    net_an = build_hdp_regcal(d_out, task_type, hp)

    # Load validation set
    (_, _), (val_X, _val_y) = ts.load_dataset(dataset_name)
    val_X = np.array(val_X)
    N = val_X.shape[0]
    bs = 256

    norms = []
    def apply_and_capture(x_np):
        x = jnp.asarray(x_np)
        # Capture all Dropout outputs; pick last 2D [B,H] tensor as head fused features
        def filt(mod, _, __):
            return isinstance(mod, nn.Dropout)
        y, col = net_an.network.apply({'params': params}, x, deterministic=True,
                                      capture_intermediates=filt, mutable=['intermediates'])
        z_cands = []
        if 'intermediates' in col:
            for scope, feats in col['intermediates'].items():
                if isinstance(feats, dict):
                    for k, lst in feats.items():
                        for t in lst:
                            arr = np.array(t)
                            if arr.ndim == 2:  # [B, H]
                                z_cands.append(arr)
        if z_cands:
            z = z_cands[-1]  # take the last 2D dropout output (head)
            n = np.linalg.norm(z, ord=2, axis=-1)  # [B]
            norms.append(n)

    for start in range(0, N, bs):
        end = min(N, start + bs)
        apply_and_capture(val_X[start:end])

    if norms:
        norms = np.concatenate(norms, axis=0)[:N]
        return _summarize(norms)
    return None

def complete(params, opt_state, trial_data):
    ds = trial_data.get('dataset')
    val = trial_data.get('val_metric')
    print(f"[Complete] {ds} final val_metric={val}")
    if ds not in ("APA", "CRI-Off", "CRI-On", "MRL", "PRS"):
        return
    hparams = trial_data.get('hyperparameters', {}) or {}
    os.makedirs('storage/noema/results/hdp_regcal_norms', exist_ok=True)
    out_path = f"storage/noema/results/hdp_regcal_norms/{ds}.json"
    try:
        summary = _collect_z_pre_norms(params, ds, hparams)
        if summary is not None:
            with open(out_path, 'w') as f:
                json.dump({'dataset': ds, 'summary': summary, 'seed': trial_data.get('seed')}, f, indent=2)
            print(f"[NormCapture] Saved {ds} z-norm summary -> {out_path}")
        else:
            print(f"[NormCapture] No norms collected for {ds}")
    except Exception as e:
        print(f"[NormCapture] Error during collection for {ds}: {e}")
